"""Reconstruct July 2023 sales from warehouse dispatches."""

import csv
import json
from decimal import Decimal
from pathlib import Path


DATASET = Path('/app/dataset')


def number(value: str) -> Decimal:
    return Decimal(value.strip().replace(',', '.'))


def answer() -> int:
    with (DATASET / 'product_catalog.csv').open(newline='') as file:
        products = list(csv.DictReader(file))

    # Dispatch 169 identifies the electric kettle by EAN instead of product ID.
    by_id = {product['product_id']: product for product in products}
    by_ean = {product['ean_code']: product for product in products}

    with (DATASET / 'temperature_logs.csv').open(newline='') as file:
        temperatures = {
            (row['timestamp'], row['zone'].strip().casefold()):
            number(row['temperature_c'])
            for row in csv.DictReader(file)
        }

    # Eight unusually large, simultaneous overnight dispatches coincide with
    # the month's only unsafe temperature event in the affected storage zones.
    # Only these clearly identified disposal records are excluded.
    disposal_ids = set(range(127, 135))
    found_disposals = set()
    dispatch_ids = set()
    revenue = Decimal(0)

    with (DATASET / 'warehouse_dispatches.csv').open(newline='') as file:
        for row in csv.DictReader(file):
            if not '2023-07-01' <= row['timestamp'] < '2023-08-01':
                continue

            dispatch_id = int(row['dispatch_id'])
            assert dispatch_id not in dispatch_ids
            dispatch_ids.add(dispatch_id)
            product = by_id.get(row['product_id'])
            if product is None:
                product = by_ean[row['product_id']]

            quantity = int(row['quantity'])
            assert number(row['total_weight_kg']) == (
                quantity * number(product['unit_weight_kg'])
            )

            if dispatch_id in disposal_ids:
                assert row['timestamp'] == '2023-07-18 03:17:00'
                zone = product['storage_category'].strip().casefold()
                assert zone in {'meat', 'frozen'}
                for timestamp in ('2023-07-18 02:00:00',
                                  '2023-07-18 04:00:00'):
                    assert temperatures[timestamp, zone] > number(
                        product['max_safe_temp_c']
                    )
                found_disposals.add(dispatch_id)
                continue

            # Matching details with distinct dispatch IDs remain sales.
            revenue += quantity * number(product['unit_price'])

    assert found_disposals == disposal_ids
    assert revenue == revenue.to_integral_value()
    return int(revenue)


if __name__ == '__main__':
    with open('/app/answer.json', 'w') as file:
        json.dump(answer(), file, default=list)
